["राज्याचे महाधिवक्ता आपला राजीनामा कोणाकडे देतात?",["उच्च न्यायालयाचे मुख्य न्यायाधीश","राज्यपाल","राष्ट्रपती","मुख्यमंत्री"],1,"राज्यपाल नियुक्ती करतात (कलम 165).",{"i":"pl8-009","y":"2019","n":22,"v":"k"}],
["योग्य विधान ओळखा (राज्य विधिमंडळ).\nअ. साधे विधेयक मंत्री किंवा खाजगी सदस्य मांडू शकतो.\nब. धन विधेयक मंत्री किंवा खाजगी सदस्य मांडू शकतो.",["फक्त अ","फक्त ब","अ व ब","एकही नाही"],0,"धन विधेयक फक्त मंत्रीच, राज्यपालांच्या शिफारशीने.",{"i":"pl8-010","y":"2026"}],
["राज्याची कार्यकारी सत्ता राज्यपालांकडे कोणत्या कलमानुसार असते?",["कलम 154","कलम 152","कलम 153","कलम 155"],0,"कलम 154; 153 – राज्यपाल पद; 155 – नियुक्ती.",{"i":"pl8-011","y":"2026"}]
