["नंदुरबारचा बाल हुतात्मा कोण?",["बाबू गेनू","शिरीषकुमार","हेमू कलानी","शंकर महाले"],1,"शिरीषकुमार मेहता (नंदुरबार) हे 9 सप्टेंबर 1942 रोजी चले जाव आंदोलनातील मिरवणुकीत पोलिसांच्या गोळीबारात हुतात्मा झाले.",{"i":"hi11-003"}],
["हैदराबाद संस्थानाविरुद्धच्या कारवाईचे नाव काय?",["ऑपरेशन विजय","ऑपरेशन पोलो","ऑपरेशन ब्लू स्टार","ऑपरेशन मेघदूत"],1,"हैदराबाद संस्थानाविरुद्ध 13–17 सप्टेंबर 1948 दरम्यान 'ऑपरेशन पोलो' ही पोलीस कारवाई झाली; 17 सप्टेंबर – मराठवाडा मुक्ती संग्राम दिन.",{"i":"hi11-004"}],
["हैदराबाद मुक्ती संग्रामाचे नेतृत्व कोणी केले?",["स्वामी रामानंद तीर्थ","नाना पाटील","यशवंतराव चव्हाण","सेनापती बापट"],0,"स्वामी रामानंद तीर्थ यांनी हैदराबाद स्टेट काँग्रेसच्या माध्यमातून हैदराबाद मुक्ती संग्रामाचे नेतृत्व केले.",{"i":"hi11-005"}],
["1942 मध्ये सातारा येथे प्रतिसरकार कोणी स्थापन केले?",["नाना पाटील","वसंतदादा पाटील","यशवंतराव चव्हाण","उद्धवराव पाटील"],0,"क्रांतिसिंह नाना पाटील यांनी 1942 मध्ये सातारा येथे 'प्रतिसरकार' (पत्री सरकार) स्थापन केले.",{"i":"hi11-006"}],
["चिमूरचा उठाव कोणत्या जिल्ह्यात झाला?",["वर्धा","चंद्रपूर","नागपूर","अमरावती"],1,"चिमूर (चंद्रपूर) येथे 16 ऑगस्ट 1942 रोजी उठाव झाला व काही दिवस ब्रिटिश सत्ता उलथवली गेली.",{"i":"hi11-007"}],
["संयुक्त महाराष्ट्र चळवळीत 'मराठा' वृत्तपत्रातून प्रचार कोणी केला?",["प्रबोधनकार ठाकरे","आचार्य अत्रे","एस. एम. जोशी","डांगे"],1,"आचार्य प्र. के. अत्रे यांनी 'मराठा' दैनिकातून (1956) संयुक्त महाराष्ट्र चळवळीचा जोरदार प्रचार केला.",{"i":"hi11-008"}]
