ge1:[
["दिवस व रात्र कशामुळे होतात?",["परिभ्रमण","परिवलन","चंद्राची गती","सूर्याची गती"],1,"पृथ्वी स्वतःभोवती फिरते (परिवलन, सुमारे 24 तास) म्हणून दिवस-रात्र होतात. सूर्याभोवती फिरण्याने (परिभ्रमण, 365¼ दिवस) ऋतू होतात.",{"i":"ge1-001"}],
["ओझोनचा थर वातावरणाच्या कोणत्या थरात आहे?",["तपांबर","स्थितांबर","मध्यांबर","आयनांबर"],1,"ओझोनचा थर स्थितांबरात (सुमारे 15–35 किमी) असतो व सूर्याचे अतिनील किरण शोषतो. हवामानाच्या घडामोडी तपांबरात होतात.",{"i":"ge1-002"}],
["पृथ्वीला 1° फिरण्यास किती वेळ लागतो?",["1 मिनिट","4 मिनिटे","15 मिनिटे","1 तास"],1,"पृथ्वी 24 तासांत 360° फिरते: 1440 मिनिटे ÷ 360 = 4 मिनिटे प्रति अंश. म्हणून 15° रेखांश = 1 तास.",{"i":"ge1-003"}],
["दख्खनचे पठार कोणत्या खडकापासून बनले आहे?",["ग्रॅनाइट","बेसॉल्ट","वालुकाश्म","संगमरवर"],1,"दख्खनचे पठार सुमारे 6.5 कोटी वर्षांपूर्वीच्या लाव्हा उद्रेकांतून बनलेल्या बेसॉल्ट (अग्निजन्य) खडकाचे आहे; म्हणून त्याला दख्खन ट्रॅप म्हणतात.",{"i":"ge1-004"}],
["सर्वात उष्ण ग्रह कोणता?",["बुध","शुक्र","मंगळ","गुरू"],1,"बुध सूर्याला सर्वात जवळ असला तरी शुक्र सर्वात उष्ण आहे, कारण त्याच्या जाड CO₂ वातावरणामुळे तीव्र हरितगृह परिणाम होतो.",{"i":"ge1-005"}],
["उत्तर गोलार्धात सर्वात मोठा दिवस कोणता?",["21 मार्च","21 जून","23 सप्टेंबर","22 डिसेंबर"],1,"21 जूनला सूर्य कर्कवृत्तावर लंबरूप असतो, म्हणून उत्तर गोलार्धात सर्वात मोठा दिवस. 22 डिसेंबर सर्वात लहान दिवस; 21 मार्च व 23 सप्टेंबर दिवस-रात्र समान.",{"i":"ge1-006"}],
["रेडिओ लहरी परावर्तित करणारा थर कोणता?",["तपांबर","स्थितांबर","आयनांबर","बाह्यांबर"],2,"आयनांबरातील विद्युतभारित कण रेडिओ लहरी पृथ्वीकडे परावर्तित करतात, म्हणून दूरवर रेडिओ संदेश जातात.",{"i":"ge1-007"}]
],
