ge2:[
["कर्कवृत्त खालीलपैकी कोणत्या राज्यातून जात नाही?",["गुजरात","महाराष्ट्र","झारखंड","मिझोराम"],1,"कर्कवृत्त 8 राज्यांतून जाते: गुजरात, राजस्थान, मध्य प्रदेश, छत्तीसगड, झारखंड, पश्चिम बंगाल, त्रिपुरा व मिझोराम. महाराष्ट्र कर्कवृत्ताच्या दक्षिणेला आहे.",{"i":"ge2-001"}],
["भारताची सर्वात लांब आंतरराष्ट्रीय सीमा कोणत्या देशासोबत आहे?",["चीन","पाकिस्तान","बांगलादेश","नेपाळ"],2,"भारत–बांगलादेश सीमा सुमारे 4,096 किमी ही सर्वात लांब; त्यानंतर चीन (सुमारे 3,488 किमी) व पाकिस्तान.",{"i":"ge2-002"}],
["भारताचे दक्षिण टोक कोणते?",["कन्याकुमारी","इंदिरा पॉइंट","रामेश्वरम","पोर्ट ब्लेअर"],1,"भारताचे दक्षिण टोक इंदिरा पॉइंट (ग्रेट निकोबार) आहे. मुख्य भूमीचे दक्षिण टोक कन्याकुमारी.",{"i":"ge2-003"}],
["क्षेत्रफळाच्या दृष्टीने भारताचा जगात कितवा क्रमांक आहे?",["5","6","7","8"],2,"क्षेत्रफळात भारत जगात सातवा: रशिया, कॅनडा, चीन, अमेरिका, ब्राझील, ऑस्ट्रेलिया, भारत. लोकसंख्येत पहिला.",{"i":"ge2-004"}],
["भारतातील सर्वात मोठा गोड्या पाण्याचा तलाव कोणता?",["सांभर","वुलर","चिलिका","दल"],1,"वुलर (जम्मू-काश्मीर) हे सर्वात मोठे गोड्या पाण्याचे सरोवर. सांभर – खाऱ्या पाण्याचे; चिलिका – सर्वात मोठे खाजण (लगून).",{"i":"ge2-005"}],
["भारत व श्रीलंका यांना कोणती सामुद्रधुनी वेगळे करते?",["पाल्कची","मलाक्का","दहा अंश","आठ अंश"],0,"पाल्कची सामुद्रधुनी भारत व श्रीलंका यांच्या मधे आहे. दहा अंश खाडी – अंदमान व निकोबार; आठ अंश – मालदीव व मिनिकॉय.",{"i":"ge2-006"}],
["हुगळी नदी ही कोणत्या नदीची वितरिका आहे?",["दामोदर","ब्रह्मपुत्रा","गंगा","पद्मा"],2,"हुगळी ही गंगेची वितरिका असून कोलकाता तिच्या काठी आहे. पद्मा हे बांगलादेशातील गंगेचे नाव.",{"i":"ge2-007","y":"2019","n":49,"v":"k"}],
["जगातील सर्वात मोठा त्रिभुज प्रदेश कोणता?",["वृंदावन","राजमुंद्री","सुंदरबन","मच्छलीपट्टणम"],2,"गंगा–ब्रह्मपुत्रेचा सुंदरबन त्रिभुज प्रदेश जगातील सर्वात मोठा; तेथील खारफुटी जंगले जागतिक वारसा स्थळ आहेत.",{"i":"ge2-008","y":"2019","n":55,"v":"k"}],
["खालीलपैकी कोणत्या राज्याची सीमा दोन देशांना लागते?",["त्रिपुरा","मणिपूर","मिझोराम","नागालँड"],2,"मिझोराम: म्यानमार व बांगलादेश. त्रिपुरा, मणिपूर व नागालँड यांची सीमा एकाच देशाला लागते.",{"i":"ge2-009","y":"2022","n":42,"v":"k"}],
["खालीलपैकी कोणती विधाने चुकीची आहेत?\nअ. उत्तराखंड, उत्तर प्रदेश, बिहार, प. बंगाल व मणिपूर यांची सीमा नेपाळला लागते.\nब. नेपाळ हा चीन व भारत यांच्यामधील भूवेष्टित देश आहे.\nक. भूतान हा नेपाळचा शेजारी देश आहे.",["अ व ब","ब व क","क व अ","फक्त क"],2,"मणिपूर नव्हे तर सिक्कीमची सीमा नेपाळला लागते; भूतान व नेपाळ यांच्यामध्ये सिक्कीम आहे.",{"i":"ge2-010","y":"2026"}],
["यमुनेच्या उपनद्या पूर्वेकडून पश्चिमेकडे क्रमाने लावा: सिंध, चंबळ, बेतवा, केन",["सिंध, चंबळ, केन, बेतवा","केन, बेतवा, सिंध, चंबळ","केन, सिंध, बेतवा, चंबळ","केन, चंबळ, बेतवा, सिंध"],1,"केन → बेतवा → सिंध → चंबळ.",{"i":"ge2-011","y":"2026"}]
],
